INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷110·太祖本纪·求言与将领任官", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/278d73db50d6b6efe72681242684d9d42d0da2d4/content/books/zizhi-tongjian/vol-290/year-0951/part-03/sources/library/jiuwudaishi-110-advice/source.txt", "note": "《旧五代史》卷110·太祖本纪·求言与将领任官，段落 jiu-wudaishi-205deb4a7860-p002653；已核上下文及传主，纸本及异文待核。", "id": "ecc81c90-ee56-5de5-8e06-d99e592bda8a"}, {"title": "旧五代史·卷110·太祖本纪·停止贡食诏书", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/278d73db50d6b6efe72681242684d9d42d0da2d4/content/books/zizhi-tongjian/vol-290/year-0951/part-03/sources/library/jiuwudaishi-110-tribute-food/source.txt", "note": "《旧五代史》卷110·太祖本纪·停止贡食诏书，段落 jiu-wudaishi-205deb4a7860-p002652；已核上下文及传主，纸本及异文待核。", "id": "195a538c-b723-500e-bc83-fc41d58a30cf"}, {"title": "旧五代史·卷111·太祖本纪·澶州任官与晋州战报", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/278d73db50d6b6efe72681242684d9d42d0da2d4/content/books/zizhi-tongjian/vol-290/year-0951/part-03/sources/library/jiuwudaishi-111-jinzhou/source.txt", "note": "《旧五代史》卷111·太祖本纪·澶州任官与晋州战报，段落 jiu-wudaishi-205deb4a7860-p002656；已核上下文及传主，纸本及异文待核。", "id": "4892b94c-c27b-5fc4-9a3c-0588e2b5636e"}, {"title": "旧五代史·卷111·太祖本纪·隰州战报", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/278d73db50d6b6efe72681242684d9d42d0da2d4/content/books/zizhi-tongjian/vol-290/year-0951/part-03/sources/library/jiuwudaishi-111-xizhou/source.txt", "note": "《旧五代史》卷111·太祖本纪·隰州战报，段落 jiu-wudaishi-205deb4a7860-p002657；已核上下文及传主，纸本及异文待核。", "id": "7504ba0b-0629-52bd-bf86-9594aecd71f2"}, {"title": "旧五代史·卷128·王敏传·杜重威幕府至澶州", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/278d73db50d6b6efe72681242684d9d42d0da2d4/content/books/zizhi-tongjian/vol-290/year-0951/part-03/sources/library/jiuwudaishi-128-wangmin-career/source.txt", "note": "《旧五代史》卷128·王敏传·杜重威幕府至澶州，段落 jiu-wudaishi-205deb4a7860-p003010；已核上下文及传主，纸本及异文待核。", "id": "e7ac0e5e-5069-525e-a1dc-4fb3ea351ce0"}, {"title": "旧五代史·卷128·王朴传·校书郎与澶州记室", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/278d73db50d6b6efe72681242684d9d42d0da2d4/content/books/zizhi-tongjian/vol-290/year-0951/part-03/sources/library/jiuwudaishi-128-wangpu-career/source.txt", "note": "《旧五代史》卷128·王朴传·校书郎与澶州记室，段落 jiu-wudaishi-205deb4a7860-p002978；已核上下文及传主，纸本及异文待核。", "id": "56c253e7-33d4-535c-843c-0efb1f179155"}, {"title": "宋史·卷252·王晏传·晋州防御", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/278d73db50d6b6efe72681242684d9d42d0da2d4/content/books/zizhi-tongjian/vol-290/year-0951/part-03/sources/library/songshi-252-wangyan-jinzhou/source.txt", "note": "《宋史》卷252·王晏传·晋州防御，段落 songshi-9c6e46fee832-p057328；已核上下文及传主，纸本及异文待核。", "id": "0d143446-eda9-52e1-9eef-5c5e0805109b"}, {"title": "宋史·卷431·崔颂传·澶州幕府", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/278d73db50d6b6efe72681242684d9d42d0da2d4/content/books/zizhi-tongjian/vol-290/year-0951/part-03/sources/library/songshi-431-cuisong-chanzhou/source.txt", "note": "《宋史》卷431·崔颂传·澶州幕府，段落 songshi-9c6e46fee832-p070920；已核上下文及传主，纸本及异文待核。", "id": "f2b88e18-4c71-5c43-a448-646e176cc3b4"}, {"title": "宋史·卷431·崔颂传·父亲与早年履历", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/278d73db50d6b6efe72681242684d9d42d0da2d4/content/books/zizhi-tongjian/vol-290/year-0951/part-03/sources/library/songshi-431-cuisong-family/source.txt", "note": "《宋史》卷431·崔颂传·父亲与早年履历，段落 songshi-9c6e46fee832-p070919；已核上下文及传主，纸本及异文待核。", "id": "c9997025-04e9-5b4c-b201-b31c8450575c"}, {"title": "资治通鉴·卷290·广顺元年·正月北汉与宋州事", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/82a6e88e766f7337f28566c6d64678bb760b98b8/content/books/zizhi-tongjian/vol-290/year-0951/part-01/sources/library/tongjian-290-951-january-court/source.txt", "note": "《资治通鉴》卷290·广顺元年·正月北汉与宋州事，段落 zizhi-tongjian-a63549944a71-p003443；已核上下文及传主，纸本及异文待核。", "id": "bb681727-9eea-5a6d-ba00-7e07450247f4"}, {"title": "旧五代史·卷110·太祖本纪·邺都任命与隐帝发丧", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/82a6e88e766f7337f28566c6d64678bb760b98b8/content/books/zizhi-tongjian/vol-290/year-0951/part-02/sources/library/jiuwudaishi-110-yedu-funeral/source.txt", "note": "《旧五代史》卷110·太祖本纪·邺都任命与隐帝发丧，段落 jiu-wudaishi-205deb4a7860-p002651；已核上下文及传主，纸本及异文待核。", "id": "5b51fc62-7627-56dc-a90c-a02ed1d0e8f0"}, {"title": "新五代史·卷11·周本纪·广顺元年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7f523fc68334366ce90d3a6e1465b179c9c38000/content/books/zizhi-tongjian/vol-290/year-0951/part-01/sources/library/xinwudaishi-011-first-year-951/source.txt", "note": "《新五代史》卷11·周本纪·广顺元年，段落 xin-wudaishi-b08f244b9241-p000368；已核上下文及传主，纸本及异文待核。", "id": "d3b793df-2c14-5468-91e6-30671d01ef09"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "窦贞固", "aliases": ["竇貞固"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：窦贞固，原节度推官、获任者。", "biography": null, "status": "draft", "id": "628caf07-3ba2-5bc4-8630-598667f5bdd0"}, {"name": "苏禹珪", "aliases": ["蘇禹珪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "密州人，任河东观察判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "b8c912f3-4f5e-5fbc-9714-9caaf03ed98c"}, {"name": "王彦超", "aliases": ["王彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "临清人，后晋护圣指挥使。946年六月受命与白延遇带所属十营兵赴邢州。生卒年未载。", "biography": null, "status": "draft", "id": "c981d4c7-7693-5ee8-a667-6ab1fccba981"}, {"name": "巩延美", "aliases": ["鞏延美", "巩庭美", "鞏庭美", "巩廷美", "鞏廷美"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘赟的右都押牙。950年刘赟离开徐州西行迎立时，与杨温留守徐州。《新五代史》刘赟传写作巩庭美，同职同伴及同一留守场景对应；生卒年本批未录。", "biography": null, "status": "draft", "id": "4df9296b-060c-55ce-9ca5-a4523a55428f"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "苏逢吉", "aliases": ["蘇逢吉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "长安人，任河东节度判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "1136d429-42fd-5166-94a0-f2dd9af9c920"}, {"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李崧。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}, {"name": "潘聿捻", "aliases": ["潘聿撚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "耶律阮的姐夫。947年正月被任命为横海节度使，原文字形为潘聿撚，展示采用捻并保留原字别名。生卒年未载。", "biography": null, "status": "draft", "id": "a77d94bc-16d8-5e81-b7da-1ea58bd7fdcb"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "耶律阮", "aliases": ["耶律兀欲", "兀欲", "永康王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "小字兀欲，东丹王耶律倍之子。《资治通鉴》947年条下称永康王，记耶律德光将李彦绅、秦继旻的家属和财产交给他。《辽史》卷五明确名阮、小字兀欲，按同一主体建档；王号具体授封时间仍须另据后文校核，生卒年暂未录。", "biography": null, "status": "draft", "id": "42a17de5-aa28-50e6-bab8-b134f0113f3f"}, {"name": "刘承钧", "aliases": ["劉承鈞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘崇的次子。951年父亲在晋阳称帝时，任侍卫亲军都指挥使、太原尹。《旧五代史》也记他是刘崇之子并任两职。生卒年本批未录。", "biography": null, "status": "draft", "id": "3f4681a7-ca79-5d5d-a5c2-53bef1936681"}, {"name": "刘崇（刘知远弟）", "aliases": ["劉崇（劉知遠弟）", "刘旻", "劉旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的弟弟，后来名刘旻。947年任太原尹、知府事。与朱温早年寄居的萧县刘崇分别建档，具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "edf0bd63-ab6d-577e-8623-9f2d759b6d97"}, {"name": "白从晖", "aliases": ["白從暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：白从晖。", "biography": null, "status": "draft", "id": "26c4d10c-35dd-51b7-abd1-cad542bc7fe1"}, {"name": "李存瑰", "aliases": ["李瓌", "李瑰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李存瑰，供奉官、赴西川赐诏者。", "biography": null, "status": "draft", "id": "a91449a7-a285-52aa-9c4a-0bf81e533f51"}, {"name": "郭崇威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "应州马军都指挥使，金城人。937年条中记载他不愿臣服契丹，独自南归。", "biography": null, "status": "draft", "id": "2f1d1823-9873-5df8-83ed-7330578213e6"}, {"name": "曹威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "真定人，950年任邺都行营步军都指挥使。刘承祐密令他与郭崇威杀郭威及监军王峻，本段尚未记实际执行。生卒年未载。", "biography": null, "status": "draft", "id": "c26ccc4f-2658-5be8-b917-885c6c56f287"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "王敏（杜重威判官）", "aliases": ["王敏（金乡）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "金乡人，杜重威的观察判官。947年杜重威叛乱时屡次哭谏，未获听从；邺都粮尽后奉杜重威表出城请降。《旧五代史》职名作节度判官。生卒年未载。", "biography": null, "status": "draft", "id": "8f7fed9a-5ef2-5c02-8b61-b0b1733a81ba"}, {"name": "崔颂", "aliases": ["崔頌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "崔协之子，原任右补阙。951年任柴荣镇宁军观察判官。《宋史》记他字敦美、河南偃师人。生卒年尚未录入。", "biography": null, "status": "draft", "id": "a4c2a1eb-81d6-50a1-a278-4196c2338a0b"}, {"name": "王朴", "aliases": ["王樸"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "东平人，原任校书郎。951年任柴荣镇宁军掌书记。《旧五代史》记他字文伯，在后汉乾祐年间中进士，后来进入澶州幕府。生卒年尚未录入。", "biography": null, "status": "draft", "id": "aef64c13-19ef-556c-96f1-dd9e8fb91844"}, {"name": "崔协", "aliases": ["崔協"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：崔协。", "biography": null, "status": "draft", "id": "56693be3-8983-515d-b1ca-96e270e13442"}, {"name": "王晏", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐州人，947年二月任奉国都头，与赵晖、侯章谋划杀死契丹将刘愿，率数名壮士夜入府署、取库中兵器。生卒年暂未录入。", "biography": null, "status": "draft", "id": "030a26f1-62e3-5876-92b4-923b763723f0"}, {"name": "安元宝", "aliases": ["安元寶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "北汉副兵马使。951年受命前去焚烧晋州西城，却向后周投降；史书未明言他是否完成焚烧。生卒年未载。", "biography": null, "status": "draft", "id": "a7f1d93e-399a-5b31-9a94-d0ff4a846569"}, {"name": "许迁", "aliases": ["許遷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "郓州人，隰州刺史。951年派耿继业在长寿村迎击北汉军，随后守住隰州。生卒年未载。", "biography": null, "status": "draft", "id": "a9f282a6-5cc5-57d8-b68f-9ee8fd9a1e5c"}, {"name": "耿继业", "aliases": ["耿繼業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "隰州步军都指挥使。951年受许迁派遣，在长寿村迎击北汉军，俘获程筠等人后将其杀死。生卒年未载。", "biography": null, "status": "draft", "id": "d28bfc1b-b7f2-5e33-b90a-86cf518adb02"}, {"name": "程筠", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 951, "description": "北汉将领。951年在长寿村被耿继业俘获并杀死。出生年未载。", "biography": null, "status": "draft", "id": "b7e4593a-430e-5e1b-99b5-b84f5a5d453e"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

